mapper.select:
/*	설  명 	: 사용자최근로그인이력조회 */
SELECT * FROM (
	SELECT	*
	FROM 	TB_LMS_USER_LGN_HSTRY
	WHERE 	1 = 1 AND USER_ID = #{userId}
	ORDER 	BY	REG_DTTM DESC
) X
WHERE ROWNUM = 1

    /*	설  명 	: 1차: EP 사용자 조회 (TB_EPO_USER + TB_EPO_USER_TP) */
        SELECT
		      U.LOGIN_ID        AS USER_ID
		    , U.INTG_NO         AS INTG_NO
		    , U.LOGIN_ID        AS USER_RPRS_ID
		    , U.PWD             AS PWD
		  FROM EP.TB_EPO_USER U
		 WHERE ( U.LOGIN_ID = #{userId}
		         OR U.INTG_NO = (
		                SELECT T2.INTG_NO
		                  FROM EP.TB_EPO_USER_TP T2
		                 WHERE T2.USER_TP_ID = #{userId}
		                   AND ROWNUM = 1
		            )
		       )

		   AND U.PWD = FURLMS.PasswordEncoder(#{userIdEncpswd})

/*	설  명 	: 2차: LMS 사용자 조회 (TB_LMS_USER) */
SELECT
      U.USER_ID         AS USER_ID
  FROM TB_LMS_USER U
 WHERE U.USER_ID = #{userId}

   AND U.USER_ID_ENCPSWD = #{userIdEncpswd}
